import { it, expect, describe } from "vitest";
import { rollingAverage, weeklyRateOfChange, totalChange, latestValue, paceClassification, isFlatTrend, isValidBodyweightLb, upsertBodyweightEntry, BODYWEIGHT_MIN_LB, BODYWEIGHT_MAX_LB } from "../bodyweightMath.js";

// Nutrition P0, step 2 — baseline coverage of the existing bodyweight-trend logic (used by
// diagnoseNutrition for the adjustment-recommendation gate). Fixed, hand-constructed entry
// sets with independently computed expected averages — not generated by the function itself.
function entry(daysAgo, weight) {
  const d = new Date();
  d.setDate(d.getDate() - daysAgo);
  return { date: d.toISOString(), weight };
}

describe("rollingAverage", () => {
  it("averages exactly the entries within the trailing window — hand-computed: (180+181+182)/3 = 181", () => {
    const entries = [entry(0, 182), entry(1, 181), entry(2, 180), entry(10, 999)]; // 10-day-old entry excluded from a 7-day window
    expect(rollingAverage(entries, "weight", 7)).toBeCloseTo(181, 5);
  });
  it("returns null when nothing falls in the window", () => {
    expect(rollingAverage([entry(30, 180)], "weight", 7)).toBeNull();
  });
});

describe("weeklyRateOfChange", () => {
  it("compares this week's average against last week's — hand-computed: 182 avg vs 180 avg = +2", () => {
    const entries = [
      entry(0, 182), entry(1, 182), entry(2, 182), // this week ~182
      entry(8, 180), entry(9, 180), entry(10, 180), // prior week ~180
    ];
    expect(weeklyRateOfChange(entries, "weight")).toBeCloseTo(2, 5);
  });
  it("returns null without two full windows of data", () => {
    expect(weeklyRateOfChange([entry(0, 180)], "weight")).toBeNull();
  });
});

describe("totalChange / latestValue", () => {
  it("totalChange is last entry minus first entry by date, not by array order", () => {
    const entries = [entry(0, 185), entry(10, 180)]; // out of chronological order in the array
    expect(totalChange(entries, "weight")).toBe(5);
  });
  it("latestValue returns the most recent dated entry", () => {
    expect(latestValue([entry(5, 180), entry(0, 185), entry(2, 182)], "weight")).toBe(185);
  });
});

describe("paceClassification", () => {
  it("classifies no data distinctly from every real pace", () => {
    expect(paceClassification(null, -1)).toBe("no_data");
  });
  it("near-zero weekly change is stalled regardless of target", () => {
    expect(paceClassification(0.1, -1)).toBe("stalled");
  });
  it("moving opposite the target direction is flagged as the wrong direction, not just 'off pace'", () => {
    expect(paceClassification(0.5, -1)).toBe("gaining"); // gaining while targeting loss
    expect(paceClassification(-0.5, 1)).toBe("losing"); // losing while targeting gain
  });
  it("within 70-140% of target rate is on_pace; beyond is too_fast or slow", () => {
    expect(paceClassification(-1.0, -1.0)).toBe("on_pace");
    expect(paceClassification(-1.5, -1.0)).toBe("too_fast");
    expect(paceClassification(-0.5, -1.0)).toBe("slow");
  });
});

describe("isFlatTrend — requires EVERY trailing weekly window to be near-zero, not just the latest one", () => {
  it("true when 3 consecutive weekly windows all show < 0.25lb change", () => {
    const entries = [];
    for (let i = 0; i < 28; i++) entries.push(entry(i, 180 + (i % 2 === 0 ? 0.05 : -0.05)));
    expect(isFlatTrend(entries, 3)).toBe(true);
  });
  it("false when only the most recent window is flat but an earlier one moved", () => {
    const entries = [
      // last 7 days flat around 180
      ...[0, 1, 2, 3, 4, 5, 6].map((i) => entry(i, 180)),
      // 8-14 days ago flat around 180 (so week-over-week looks flat for window 0)
      ...[7, 8, 9, 10, 11, 12, 13].map((i) => entry(i, 180)),
      // 15-21 days ago was meaningfully higher — the 2nd trailing window should catch this
      ...[14, 15, 16, 17, 18, 19, 20].map((i) => entry(i, 183)),
    ];
    expect(isFlatTrend(entries, 3)).toBe(false);
  });
  it("false (not true) when there isn't enough history to back the claim — never a false positive from sparse data", () => {
    expect(isFlatTrend([entry(0, 180), entry(1, 180)], 3)).toBe(false);
  });
});

describe("isValidBodyweightLb — sanity bounds", () => {
  it("accepts plausible values", () => {
    expect(isValidBodyweightLb(180)).toBe(true);
    expect(isValidBodyweightLb(BODYWEIGHT_MIN_LB)).toBe(true);
    expect(isValidBodyweightLb(BODYWEIGHT_MAX_LB)).toBe(true);
  });
  it("rejects obvious typos/impossible values", () => {
    expect(isValidBodyweightLb(-10)).toBe(false);
    expect(isValidBodyweightLb(0)).toBe(false);
    expect(isValidBodyweightLb(5000)).toBe(false); // stray extra digit
    expect(isValidBodyweightLb(NaN)).toBe(false);
    expect(isValidBodyweightLb("180")).toBe(false);
  });
});

describe("upsertBodyweightEntry", () => {
  it("creates a new entry when none exists for today", () => {
    const result = upsertBodyweightEntry([], { weight: 180 });
    expect(result).toHaveLength(1);
    expect(result[0].weight).toBe(180);
  });
  it("updates today's entry in place rather than creating a duplicate", () => {
    const today = new Date();
    const existing = [{ id: "bw_1", date: today.toISOString(), weight: 180, waist: null, bodyFat: null, notes: "" }];
    const result = upsertBodyweightEntry(existing, { weight: 181 }, { date: today });
    expect(result).toHaveLength(1);
    expect(result[0].weight).toBe(181);
    expect(result[0].id).toBe("bw_1");
  });
  it("a partial save (e.g. just waist) never nulls out a value already entered today from elsewhere", () => {
    const today = new Date();
    const existing = [{ id: "bw_1", date: today.toISOString(), weight: 180, waist: null, bodyFat: null, notes: "" }];
    const result = upsertBodyweightEntry(existing, { waist: 34 }, { date: today });
    expect(result[0].weight).toBe(180); // preserved, not nulled
    expect(result[0].waist).toBe(34);
  });
});
